public void appendItemLayers(
        final ItemStackRenderState output,
        final ItemStack item,
        final ItemDisplayContext displayContext,
        final @Nullable Level level,
        final @Nullable ItemOwner owner,
        final int seed
    ) {
        Identifier modelId = item.get(DataComponents.ITEM_MODEL);
        if (modelId != null) {
            output.setOversizedInGui(this.getItemProperties(modelId).oversizedInGui());
            this.getItemModel(modelId).update(output, item, this, displayContext, level instanceof ClientLevel clientLevel ? clientLevel : null, owner, seed);
        }
    }

public void updateForTopItem(
        final ItemStackRenderState output,
        final ItemStack item,
        final ItemDisplayContext displayContext,
        final @Nullable Level level,
        final @Nullable ItemOwner owner,
        final int seed
    ) {
        output.clear();
        if (!item.isEmpty()) {
            output.displayContext = displayContext;
            this.appendItemLayers(output, item, displayContext, level, owner, seed);
        }
    }

public ItemStackRenderState.LayerRenderState newLayer() {
        this.ensureCapacity(1);
        return this.layers[this.activeLayerCount++];
    }

public void ensureCapacity(final int requestedCount) {
        int currentCapacity = this.layers.length;
        int requiredNewCapacity = this.activeLayerCount + requestedCount;
        if (requiredNewCapacity > currentCapacity) {
            this.layers = Arrays.copyOf(this.layers, requiredNewCapacity);

            for (int i = currentCapacity; i < requiredNewCapacity; i++) {
                this.layers[i] = new ItemStackRenderState.LayerRenderState();
            }
        }
    }

public List<BakedQuad> prepareQuadList() {
            return this.quads;
        }

public void submit(
        final PoseStack poseStack, final SubmitNodeCollector submitNodeCollector, final int lightCoords, final int overlayCoords, final int outlineColor
    ) {
        for (int i = 0; i < this.activeLayerCount; i++) {
            this.layers[i].submit(poseStack, submitNodeCollector, lightCoords, overlayCoords, outlineColor);
        }
    }

private void submit(
            final PoseStack poseStack, final SubmitNodeCollector submitNodeCollector, final int lightCoords, final int overlayCoords, final int outlineColor
        ) {
            poseStack.pushPose();
            this.applyTransform(poseStack.last());
            if (this.specialRenderer != null) {
                this.specialRenderer
                    .submit(
                        this.argumentForSpecialRendering,
                        poseStack,
                        submitNodeCollector,
                        lightCoords,
                        overlayCoords,
                        this.foilType != ItemStackRenderState.FoilType.NONE,
                        outlineColor
                    );
            } else {
                int[] tints = this.tintLayers != null ? this.tintLayers.toArray(EMPTY_TINTS) : EMPTY_TINTS;
                submitNodeCollector.submitItem(
                    poseStack, ItemStackRenderState.this.displayContext, lightCoords, overlayCoords, outlineColor, tints, this.quads, this.foilType
                );
            }

            poseStack.popPose();
        }

private void applyTransform(final PoseStack.Pose localPose) {
            this.itemTransform.apply(ItemStackRenderState.this.displayContext.leftHand(), localPose);
            localPose.mulPose(this.localTransform);
        }

@Override
    public void submitItem(
        final PoseStack poseStack,
        final ItemDisplayContext displayContext,
        final int lightCoords,
        final int overlayCoords,
        final int outlineColor,
        final int[] tintLayers,
        final List<BakedQuad> quads,
        final ItemStackRenderState.FoilType foilType
    ) {
        this.order(0).submitItem(poseStack, displayContext, lightCoords, overlayCoords, outlineColor, tintLayers, quads, foilType);
    }

@Override
    public void submitItem(
        final PoseStack poseStack,
        final ItemDisplayContext displayContext,
        final int lightCoords,
        final int overlayCoords,
        final int outlineColor,
        final int[] tintLayers,
        final List<BakedQuad> quads,
        final ItemStackRenderState.FoilType foilType
    ) {
        this.wasUsed = true;
        this.itemSubmits
            .add(
                new SubmitNodeStorage.ItemSubmit(poseStack.last().copy(), displayContext, lightCoords, overlayCoords, outlineColor, tintLayers, quads, foilType)
            );
    }

public List<SubmitNodeStorage.ItemSubmit> getItemSubmits() {
        return this.itemSubmits;
    }

public void renderSolid(
        final SubmitNodeCollection nodeCollection, final MultiBufferSource.BufferSource bufferSource, final OutlineBufferSource outlineBufferSource
    ) {
        for (SubmitNodeStorage.ItemSubmit submit : nodeCollection.getItemSubmits()) {
            if (!hasTranslucency(submit)) {
                this.renderItem(bufferSource, outlineBufferSource, submit);
            }
        }
    }

public void renderTranslucent(
        final SubmitNodeCollection nodeCollection, final MultiBufferSource.BufferSource bufferSource, final OutlineBufferSource outlineBufferSource
    ) {
        for (SubmitNodeStorage.ItemSubmit submit : nodeCollection.getItemSubmits()) {
            if (hasTranslucency(submit)) {
                this.renderItem(bufferSource, outlineBufferSource, submit);
            }
        }
    }

private static boolean hasTranslucency(final SubmitNodeStorage.ItemSubmit submit) {
        for (BakedQuad quad : submit.quads()) {
            if (quad.materialInfo().itemRenderType().hasBlending()) {
                return true;
            }
        }

        return false;
    }

private void renderItem(
        final MultiBufferSource.BufferSource bufferSource, final OutlineBufferSource outlineBufferSource, final SubmitNodeStorage.ItemSubmit submit
    ) {
        PoseStack.Pose pose = submit.pose();
        ItemStackRenderState.FoilType foilType = submit.foilType();
        PoseStack.Pose foilDecalPose = foilType == ItemStackRenderState.FoilType.SPECIAL ? computeFoilDecalPose(submit.displayContext(), pose) : null;
        this.quadInstance.setLightCoords(submit.lightCoords());
        this.quadInstance.setOverlayCoords(submit.overlayCoords());
        if (submit.outlineColor() != 0) {
            outlineBufferSource.setColor(submit.outlineColor());
        }

        for (BakedQuad quad : submit.quads()) {
            BakedQuad.MaterialInfo material = quad.materialInfo();
            RenderType renderType = material.itemRenderType();
            this.quadInstance.setColor(getLayerColorSafe(submit.tintLayers(), material));
            if (foilType != ItemStackRenderState.FoilType.NONE) {
                VertexConsumer foilBuffer = getFoilBuffer(bufferSource, renderType, foilDecalPose);
                foilBuffer.putBakedQuad(pose, quad, this.quadInstance);
            }

            if (submit.outlineColor() != 0) {
                outlineBufferSource.getBuffer(renderType).putBakedQuad(pose, quad, this.quadInstance);
            }

            bufferSource.getBuffer(renderType).putBakedQuad(pose, quad, this.quadInstance);
        }
    }

private static int getLayerColorSafe(final int[] layers, final int layer) {
        return layer >= 0 && layer < layers.length ? layers[layer] : -1;
    }

private static int getLayerColorSafe(final int[] tintLayers, final BakedQuad.MaterialInfo material) {
        return material.isTinted() ? getLayerColorSafe(tintLayers, material.tintIndex()) : -1;
    }

default void putBakedQuad(final PoseStack.Pose pose, final BakedQuad quad, final QuadInstance instance) {
        Vector3fc normalVec = quad.direction().getUnitVec3f();
        Matrix4f matrix = pose.pose();
        Vector3f normal = pose.transformNormal(normalVec, new Vector3f());
        int lightEmission = quad.materialInfo().lightEmission();

        for (int vertex = 0; vertex < 4; vertex++) {
            Vector3fc position = quad.position(vertex);
            long packedUv = quad.packedUV(vertex);
            int vertexColor = instance.getColor(vertex);
            int light = instance.getLightCoordsWithEmission(vertex, lightEmission);
            Vector3f pos = matrix.transformPosition(position, new Vector3f());
            float u = UVPair.unpackU(packedUv);
            float v = UVPair.unpackV(packedUv);
            this.addVertex(pos.x(), pos.y(), pos.z(), vertexColor, u, v, instance.overlayCoords(), light, normal.x(), normal.y(), normal.z());
        }
    }

public static long pack(final float u, final float v) {
        long high = Float.floatToIntBits(u) & 4294967295L;
        long low = Float.floatToIntBits(v) & 4294967295L;
        return high << 32 | low;
    }

public static float unpackU(final long packedUV) {
        int bits = (int)(packedUV >> 32);
        return Float.intBitsToFloat(bits);
    }

public static float unpackV(final long packedUV) {
        return Float.intBitsToFloat((int)packedUV);
    }

public Vector3fc position(final int vertex) {
        return switch (vertex) {
            case 0 -> this.position0;
            case 1 -> this.position1;
            case 2 -> this.position2;
            case 3 -> this.position3;
            default -> throw new IndexOutOfBoundsException(vertex);
        };
    }

public long packedUV(final int vertex) {
        return switch (vertex) {
            case 0 -> this.packedUV0;
            case 1 -> this.packedUV1;
            case 2 -> this.packedUV2;
            case 3 -> this.packedUV3;
            default -> throw new IndexOutOfBoundsException(vertex);
        };
    }

public boolean isTinted() {
            return this.tintIndex != -1;
        }

public RenderBuffers(final int maxSectionBuilders) {
        this.sectionBufferPool = SectionBufferBuilderPool.allocate(maxSectionBuilders);
        SequencedMap<RenderType, ByteBufferBuilder> fixedBuffers = Util.make(new Object2ObjectLinkedOpenHashMap<>(), map -> {
            map.put(Sheets.cutoutBlockItemSheet(), this.fixedBufferPack.buffer(ChunkSectionLayer.CUTOUT));
            map.put(Sheets.translucentBlockItemSheet(), this.fixedBufferPack.buffer(ChunkSectionLayer.TRANSLUCENT));
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, Sheets.cutoutItemSheet());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, Sheets.translucentItemSheet());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, RenderTypes.armorEntityGlint());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, RenderTypes.glint());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, RenderTypes.glintTranslucent());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, RenderTypes.entityGlint());
            put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, RenderTypes.waterMask());
        });
        this.bufferSource = MultiBufferSource.immediateWithBuffers(fixedBuffers, new ByteBufferBuilder(786432));
        this.outlineBufferSource = new OutlineBufferSource();
        SequencedMap<RenderType, ByteBufferBuilder> crumblingBuffers = Util.make(
            new Object2ObjectLinkedOpenHashMap<>(),
            map -> ModelBakery.DESTROY_TYPES.forEach(type -> put((Object2ObjectLinkedOpenHashMap<RenderType, ByteBufferBuilder>)map, type))
        );
        this.crumblingBufferSource = MultiBufferSource.immediateWithBuffers(crumblingBuffers, new ByteBufferBuilder(0));
    }
